/* The Reader and sample importer share one text coordinate space. */
const EPUBDocument={parse(raw){const parsed=new DOMParser().parseFromString(raw,'application/xhtml+xml');let doc;if(parsed.querySelector('parsererror'))doc=new DOMParser().parseFromString(raw,'text/html');else{doc=document.implementation.createHTMLDocument('');const body=[...parsed.getElementsByTagName('*')].find(n=>n.localName==='body');if(!body)throw new Error('Chapter body missing.');doc.body.replaceChildren(...[...body.childNodes].map(n=>doc.importNode(n,true)))}doc.querySelectorAll('script,style,link,iframe,object,embed,form,input,button,textarea,select,video,audio,source,svg,math,base,meta').forEach(n=>n.remove());return doc}};
